parameters.jsCode:
const body = $json.body ?? {};
const c = body.cliente ?? {};
const errores = [];
const texto = (v) => (v === undefined || v === null) ? '' : String(v).trim();

const sqlTexto = (v) => "'" + String(v).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'";

const limpio = texto(c.rut).replace(/[.\s]/g, '').toUpperCase();
const m = /^(\d{7,8})-([\dK])$/.exec(limpio);
let rut = '';
if (m) {
  let suma = 0;
  let mult = 2;
  for (let i = m[1].length - 1; i >= 0; i--) {
    suma += Number(m[1][i]) * mult;
    mult = mult === 7 ? 2 : mult + 1;
  }
  const r = 11 - (suma % 11);
  const dv = r === 11 ? '0' : r === 10 ? 'K' : String(r);
  if (dv === m[2]) rut = m[1] + '-' + dv;
}
if (!rut) errores.push('RUT del cliente inválido');

const cliente = {
  rut,
  nombre: texto(c.nombre),
  telefono: texto(c.telefono),
  email: texto(c.email).toLowerCase(),
  direccion_despacho: texto(c.direccion_despacho),
  comuna: texto(c.comuna),
};
if (!cliente.nombre) errores.push('Falta el nombre del cliente');
if (!cliente.telefono) errores.push('Falta el teléfono del cliente');
if (!cliente.direccion_despacho) errores.push('Falta la dirección de despacho');
if (!cliente.comuna) errores.push('Falta la comuna');
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(cliente.email)) errores.push('Email inválido');

const fecha = body.fecha_compra ? DateTime.fromISO(String(body.fecha_compra), { setZone: true }) : DateTime.now();
if (!fecha.isValid) errores.push('fecha_compra no tiene un formato de fecha válido');
const fecha_compra = fecha.isValid ? fecha.setZone('America/Santiago').toFormat('yyyy-MM-dd HH:mm:ss') : '';

const lista = Array.isArray(body.items) ? body.items : [];
if (lista.length === 0) errores.push('El pedido no trae productos');
const cantidades = {};
for (const it of lista) {
  const id = Number(it.id_producto);
  const cant = Number(it.cantidad);
  if (!Number.isInteger(id) || id <= 0 || !Number.isInteger(cant) || cant <= 0) {
    errores.push('Cada producto necesita id_producto y cantidad enteros positivos');
    break;
  }
  cantidades[id] = (cantidades[id] ?? 0) + cant;
}
const items = Object.keys(cantidades).map((id) => ({ id_producto: Number(id), cantidad: cantidades[id] }));

return {
  json: {
    valido: errores.length === 0,
    errores,
    cliente,
    fecha_compra,
    items,
    sql: {
      rut: sqlTexto(cliente.rut),
      nombre: sqlTexto(cliente.nombre),
      telefono: sqlTexto(cliente.telefono),
      email: sqlTexto(cliente.email),
      direccion_despacho: sqlTexto(cliente.direccion_despacho),
      comuna: sqlTexto(cliente.comuna),
      fecha_compra: sqlTexto(fecha_compra),
      ids_productos: items.map((i) => i.id_producto).join(', '),
      cantidad_por_producto: items.map((i) => 'WHEN ' + i.id_producto + ' THEN ' + i.cantidad).join(' '),
    },
  },
};

